function validate(input) {
  const [n, threads, starts] = input;
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n must be an integer from 1 to 1000.';
  if (threads.length !== 3 || [...threads].sort().join() !== 'even,odd,zero') return 'threads must list "zero", "even" and "odd" once each.';
  if (starts.length !== 3) return 'starts needs 3 start times, one per thread.';
  if (!starts.every((t) => Number.isInteger(t) && t >= 0 && t <= 1000)) return 'Each start time is an integer from 0 to 1000 ms.';
  return null;
}

