function adapt(input, solve, kit) {
  const [n, threads, starts] = input, start = Date.now(), prints = [];
  const allowed = { zero: (x) => x === 0, even: (x) => x % 2 === 0 && x >= 2 && x <= n, odd: (x) => x % 2 === 1 && x <= n };
  const zeo = new solve(n);
  for (const name of threads) if (!zeo || typeof zeo[name] !== 'function') throw new Error(`ZeroEvenOdd needs a method ${name}.`);
  let failure = null;
  threads.forEach((name, i) => {
    const printNumber = (x) => {
      if (!Number.isInteger(x) || !allowed[name](x)) failure = failure ?? `${name}() may not print ${x}.`;
      prints.push({ text: String(x), t: Date.now() - start });
      kit.trace(`${name}() prints ${x}`);
    };
    setTimeout(() => {
      kit.trace(`Thread ${'ABC'[i]} starts and calls ${name}()`);
      const result = zeo[name](printNumber);
      if (result && typeof result.then === 'function') result.then(null, (error) => { failure = failure ?? `${name}() failed: ${error && error.message || error}`; });
    }, starts[i]);
  });
  // A correct solution has printed everything by the last start; the extra time shows late prints.
  return new Promise((resolve, reject) => setTimeout(() => {
    if (failure) reject(new Error(failure));
    else resolve({ output: prints.map((p) => p.text).join(''), times: prints.map((p) => p.t) });
  }, Math.max(...starts) + 50));
}

