class ZeroEvenOdd {
  constructor(n) {
    this.n = n;
    this.turn = 'zero';
    this.parked = new Map();
  }

  waitTurn(name) {
    if (this.turn === name) return Promise.resolve();
    return new Promise((resolve) => {
      this.parked.set(name, resolve);
    });
  }

  giveTurn(name) {
    this.turn = name;
    const wake = this.parked.get(name);
    this.parked.delete(name);
    if (wake) wake();
  }

  async zero(printNumber) {
    for (let i = 1; i <= this.n; i++) {
      await this.waitTurn('zero');
      printNumber(0);
      this.giveTurn(i % 2 === 1 ? 'odd' : 'even');
    }
  }

  async even(printNumber) {
    for (let i = 2; i <= this.n; i += 2) {
      await this.waitTurn('even');
      printNumber(i);
      this.giveTurn('zero');
    }
  }

  async odd(printNumber) {
    for (let i = 1; i <= this.n; i += 2) {
      await this.waitTurn('odd');
      printNumber(i);
      this.giveTurn('zero');
    }
  }
}

