class ZeroEvenOdd {
  constructor(n) {
    this.n = n;
    this.next = 0;
    this.printers = new Map();
  }

  // Position k of the sequence: even k is a zero, odd k is the number (k + 1) / 2.
  owner(k) {
    if (k % 2 === 0) return 'zero';
    return ((k + 1) / 2) % 2 === 0 ? 'even' : 'odd';
  }

  // Record the arriving printer, then print every position whose owner has arrived.
  arrive(name, printNumber) {
    this.printers.set(name, printNumber);
    while (this.next < 2 * this.n && this.printers.has(this.owner(this.next))) {
      const k = this.next++;
      this.printers.get(this.owner(k))(k % 2 === 0 ? 0 : (k + 1) / 2);
    }
  }

  zero(printNumber) { this.arrive('zero', printNumber); }
  even(printNumber) { this.arrive('even', printNumber); }
  odd(printNumber) { this.arrive('odd', printNumber); }
}

