function generate(rand, size) {
  const n = size === 'small' ? 1 + Math.floor(rand() * 12) : 900 + Math.floor(rand() * 101);
  const threads = ['zero', 'even', 'odd'];
  for (let i = 2; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [threads[i], threads[j]] = [threads[j], threads[i]];
  }
  const top = size === 'small' ? 30 : 1000, roll = rand();
  const same = Math.floor(rand() * (top + 1));
  const starts = threads.map(() => (roll < 0.25 ? 0 : roll < 0.4 ? same : Math.floor(rand() * (top + 1))));
  return [n, threads, starts];
}
